import { requireNonEmpty, requireNonNegativeInteger } from '../shared/guards';
import { Quantity } from './Quantity';

export interface OrderLineSnapshot {
  readonly productId: string;
  readonly quantity: number;
  readonly unitPriceCents: number;
}

/** A quantity of one product at the unit price it had when the order was placed. */
export class OrderLine {
  private constructor(
    readonly productId: string,
    readonly quantity: Quantity,
    readonly unitPriceCents: number,
  ) {}

  static create(props: OrderLineSnapshot): OrderLine {
    return new OrderLine(
      requireNonEmpty(props.productId, 'productId'),
      Quantity.of(props.quantity),
      requireNonNegativeInteger(props.unitPriceCents, 'unitPriceCents'),
    );
  }

  get subtotalCents(): number {
    return this.unitPriceCents * this.quantity.value;
  }

  toSnapshot(): OrderLineSnapshot {
    return {
      productId: this.productId,
      quantity: this.quantity.value,
      unitPriceCents: this.unitPriceCents,
    };
  }
}

